var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var names=new[]{"Wand_Weapon","Garlic_Weapon","Whip_Weapon","Axe_Weapon","Bible_Weapon","Cross_Weapon"};var lines=new System.Collections.Generic.List<string>();foreach(var name in names){var go=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<UnityEngine.Transform>(true)).Select(t=>t.gameObject).FirstOrDefault(g=>g.name==name);if(go==null){lines.Add(name+" NOT FOUND");continue;}lines.Add(name+" parent="+(go.transform.parent?go.transform.parent.name:"ROOT")+" active="+go.activeSelf);foreach(var t in go.GetComponentsInChildren<UnityEngine.Transform>(true))lines.Add("  "+t.name+" components="+string.Join(",",t.GetComponents<Component>().Where(c=>c!=null).Select(c=>c.GetType().Name)));}return string.Join("\n",lines);
